  return ((doubled & 0xff) ^ ((value & 0x80) !== 0 ? 0x1b : 0x00)) & 0xff;
}

export function multiply(left, right) {
  let result = 0;
  let multiplicand = left & 0xff;
  let multiplier = right & 0xff;

  while (multiplier !== 0) {
    if ((multiplier & 1) !== 0) {
      result ^= multiplicand;
    }

    multiplicand = xtime(multiplicand);
    multiplier >>>= 1;
  }

  return result;
}

function rotateLeft8(value, bits) {
  return ((value << bits) | (value >>> (8 - bits))) & 0xff;
}

export function multiplicativeInverse(value) {
  if (value === 0) {
    return 0;
  }

  let result = 1;
  let power = value & 0xff;
  let exponent = 254;

  while (exponent > 0) {
    if ((exponent & 1) !== 0) {
      result = multiply(result, power);
    }

    power = multiply(power, power);
    exponent >>>= 1;
  }

  return result;
}

