function rotateWordInPlace(word) {
  const first = word[0];
  word[0] = word[1];
  word[1] = word[2];
  word[2] = word[3];
  word[3] = first;
}

function subWordInPlace(word) {
  word[0] = S_BOX[word[0]];
  word[1] = S_BOX[word[1]];
  word[2] = S_BOX[word[2]];
  word[3] = S_BOX[word[3]];
}

export function expandKey(keyBytes) {
  validateKeyLength(keyBytes.length);

  const nk = keyBytes.length / 4;
  const rounds = nk + 6;
  const totalWords = 4 * (rounds + 1);
  const roundKeys = new Uint8Array(totalWords * 4);
  const temp = new Uint8Array(4);

  roundKeys.set(keyBytes);

  for (let wordIndex = nk; wordIndex < totalWords; wordIndex += 1) {
    const previousOffset = (wordIndex - 1) * 4;
    temp[0] = roundKeys[previousOffset];
    temp[1] = roundKeys[previousOffset + 1];
    temp[2] = roundKeys[previousOffset + 2];
    temp[3] = roundKeys[previousOffset + 3];

    if (wordIndex % nk === 0) {
      rotateWordInPlace(temp);
      subWordInPlace(temp);
      temp[0] ^= RCON[wordIndex / nk];
    } else if (nk > 6 && wordIndex % nk === 4) {
      subWordInPlace(temp);
    }

    const sourceOffset = (wordIndex - nk) * 4;
    const targetOffset = wordIndex * 4;
    roundKeys[targetOffset] = roundKeys[sourceOffset] ^ temp[0];
    roundKeys[targetOffset + 1] = roundKeys[sourceOffset + 1] ^ temp[1];
    roundKeys[targetOffset + 2] = roundKeys[sourceOffset + 2] ^ temp[2];
    roundKeys[targetOffset + 3] = roundKeys[sourceOffset + 3] ^ temp[3];
  }

  return { roundKeys, rounds };
}

